//! Wire-format codecs with byte-identity to their CPython counterparts.
//!
//! Everything laila serialises (pickle, msgpack, `.npy`, zlib, base64,
//! Fernet, the recovery-code Python source strings) is produced here so that
//! bytes written by one language are read by the other. Each module is
//! checked against `codecs.json` (generated by the real CPython / msgpack /
//! numpy / cryptography) in `tests/vectors`.

pub mod base64;
pub mod fernet;
pub mod msgpack;
pub mod npy;
pub mod pickle;
pub mod recovery_codes;
pub mod zlib;
